func clienteFixado(digestoEsperado [32]byte) *http.Client {
	config := &tls.Config{
		InsecureSkipVerify: true, // a cadeia é substituída pela checagem abaixo
		VerifyPeerCertificate: func(brutos [][]byte, _ [][]*x509.Certificate) error {
			if len(brutos) == 0 || sha256.Sum256(brutos[0]) != digestoEsperado {
				return errors.New("certificado não confere")
			}
			return nil
		},
	}
	return &http.Client{Transport: &http.Transport{TLSClientConfig: config}}
}

