func proxyAutenticado(destino *url.URL, usuario string) *httputil.ReverseProxy {
	p := httputil.NewSingleHostReverseProxy(destino)
	base := p.Director
	p.Director = func(req *http.Request) {
		base(req)
		// a origem autoriza por este cabeçalho, que o cliente apaga via Connection
		req.Header.Set("X-Usuario", usuario)
	}
	return p
}

