func proxyEstatico(destino *url.URL) *httputil.ReverseProxy {
	p := httputil.NewSingleHostReverseProxy(destino)
	base := p.Director
	p.Director = func(req *http.Request) {
		base(req)
		// só ajusta o caminho; nenhum cabeçalho de confiança é injetado
		req.URL.Path = "/estatico" + req.URL.Path
	}
	return p
}

